<?php
declare(strict_types=1);
$env=[];foreach([__DIR__.'/.env','C:\\plantel\\DATOS_LOCALES\\plantel.env']as$f){if(is_readable($f))foreach(file($f,FILE_IGNORE_NEW_LINES|FILE_SKIP_EMPTY_LINES)as$l){if(!str_contains($l,'='))continue;[$k,$v]=explode('=',$l,2);$env[trim($k)]=trim($v," \t\"'");}}
$g=fn($k,$d='')=>(getenv($k)!==false&&getenv($k)!=='')?getenv($k):($env[$k]??$d);$h=fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$fmt=fn($v,$d=0)=>number_format((float)$v,$d,',','.');
$period=preg_match('/^\d{6}$/',(string)($_GET['periodo']??''))?$_GET['periodo']:date('Ym');$from=preg_match('/^\d{6}$/',(string)($_GET['desde']??''))?$_GET['desde']:$period;$to=preg_match('/^\d{6}$/',(string)($_GET['hasta']??''))?$_GET['hasta']:$period;$types=['TODOS'=>'Todos','FIBRA'=>'FIBRA','FIBRA+IPTV'=>'FIBRA+IPTV','FIBRA+IPTV_SD'=>'FIBRA+IPTV_SD','IPTV'=>'IPTV'];$type=strtoupper(trim((string)($_GET['tipo']??'TODOS')));if(!isset($types[$type]))$type='TODOS';$months=['01'=>'Enero','02'=>'Febrero','03'=>'Marzo','04'=>'Abril','05'=>'Mayo','06'=>'Junio','07'=>'Julio','08'=>'Agosto','09'=>'Septiembre','10'=>'Octubre','11'=>'Noviembre','12'=>'Diciembre'];$label=fn($p)=>($months[substr($p,4,2)]??$p).' '.substr($p,0,4);$periods=[];$rows=[];$current=[];$error='';
try{$pdo=new PDO('mysql:host='.$g('DB_HOSTINGER_LAB_HOST').';port='.$g('DB_HOSTINGER_LAB_PORT','3306').';dbname='.$g('DB_HOSTINGER_LAB_DATABASE').';charset=utf8mb4',$g('DB_HOSTINGER_LAB_USER'),$g('DB_HOSTINGER_LAB_PASSWORD'),[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$periods=array_column($pdo->query("SELECT DISTINCT periodo FROM raw_dataflow_toa_instalaciones ORDER BY periodo DESC LIMIT 36")->fetchAll(),'periodo');$filter=$type==='TODOS'?'':" AND LOWER(TRIM(JSON_UNQUOTE(JSON_EXTRACT(datos_json,'$.tecnologia'))))=LOWER(?)";$p=[$from,$to];if($type!=='TODOS')$p[]=$type;$q=$pdo->prepare("SELECT JSON_UNQUOTE(JSON_EXTRACT(datos_json,'$.zona22')) zona,JSON_UNQUOTE(JSON_EXTRACT(datos_json,'$.fecha_de_cita')) fecha,COUNT(*) n FROM raw_dataflow_toa_instalaciones WHERE periodo BETWEEN ? AND ?$filter GROUP BY zona,fecha");$q->execute($p);$z=[];foreach(['ZONA 1 - AMBA','ZONA 2 - LA PLATA','ZONA 3 - PROV. BS.AS']as$n)$z[$n]=['h'=>0,'s'=>0,'dh'=>[],'ds'=>[]];foreach($q as$r){if(!isset($z[$r['zona']]))continue;$d=DateTimeImmutable::createFromFormat('d/m/Y',substr((string)$r['fecha'],0,10))?:DateTimeImmutable::createFromFormat('Y-m-d',substr((string)$r['fecha'],0,10));if(!$d)continue;$k=$d->format('N')==='6'?'s':((int)$d->format('N')<6?'h':'');if(!$k)continue;$z[$r['zona']][$k]+=(int)$r['n'];$z[$r['zona']]['d'. $k][$d->format('Y-m-d')]=1;}$p=[$period];if($type!=='TODOS')$p[]=$type;$q=$pdo->prepare("SELECT JSON_UNQUOTE(JSON_EXTRACT(datos_json,'$.zona22')) zona,COUNT(*) n FROM raw_dataflow_toa_instalaciones WHERE periodo=? AND UPPER(JSON_UNQUOTE(JSON_EXTRACT(datos_json,'$.estado_de_la_orden')))='COMPLETADO' AND LOWER(JSON_UNQUOTE(JSON_EXTRACT(datos_json,'$.alta'))) IN ('true','1','si','sí')$filter GROUP BY zona");$q->execute($p);foreach($q as$r)$current[$r['zona']]=(int)$r['n'];$cfg=json_decode((string)@file_get_contents('C:\\plantel\\matrix\\config\\objetivos_toa.json'),true)?:[];$goal=$cfg[$period]??[];$now=date('Ym');$rh=$rs=0;if($period>$now){$rh=(int)($goal['dias_habiles']??0);$rs=(int)($goal['sabados']??0);}elseif($period===$now){$d=new DateTimeImmutable('tomorrow');$last=new DateTimeImmutable('last day of this month');for(;$d<=$last;$d=$d->modify('+1 day')){if($d->format('N')==='6')$rs++;elseif((int)$d->format('N')<6)$rh++;}}$make=function($name,$list)use(&$z,&$current,$rh,$rs,$goal){$h=$s=0;$dh=[];$ds=[];foreach($list as$n){$h+=$z[$n]['h'];$s+=$z[$n]['s'];$dh+=$z[$n]['dh'];$ds+=$z[$n]['ds'];}$actual=$name==='Zona 3'?($current['ZONA 3 - PROV. BS.AS']??0):(($current['ZONA 1 - AMBA']??0)+($current['ZONA 2 - LA PLATA']??0));$projection=$actual+(count($dh)?$h/count($dh):0)*$rh+(count($ds)?$s/count($ds):0)*$rs;$target=$name==='Zona 3'?($goal['zona3']??0):($goal['zona12']??0);return['name'=>$name,'actual'=>$actual,'projection'=>$projection,'target'=>$target,'diff'=>$projection-$target,'week'=>$h/(count($dh)?:1),'sat'=>$s/(count($ds)?:1)];};$rows=[$make('Zona 3',['ZONA 3 - PROV. BS.AS']),$make('Zona 1 + 2',['ZONA 1 - AMBA','ZONA 2 - LA PLATA'])];}catch(Throwable$e){$error='No se pudo cargar la proyección en este momento.';error_log($e->getMessage());}$actual=array_sum(array_column($rows,'actual'));$projection=array_sum(array_column($rows,'projection'));$target=array_sum(array_column($rows,'target'));?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Proyección de altas</title><style>body{margin:0;background:#e8f0f3;color:#172033;font:14px system-ui,sans-serif}main{max-width:1320px;margin:auto;padding:22px}.head{display:flex;justify-content:space-between;gap:18px;align-items:end}.sub{color:#647589;font-size:12px}.filters,.card,.box{background:#fff;border:1px solid #c5d5de;border-radius:9px}.filters{display:flex;gap:8px;align-items:end;flex-wrap:wrap;padding:12px}label{display:grid;gap:4px;color:#415063;font-size:11px;font-weight:700}select,button{height:36px;border-radius:7px;font:inherit}select{border:1px solid #c5d5de;padding:0 8px}button{background:#087f8c;color:#fff;border:0;padding:0 15px;font-weight:700}.cards{display:grid;grid-template-columns:repeat(5,1fr);gap:10px;margin:18px 0 12px}.card{padding:13px 15px}.card span{display:block;color:#647589;font-size:11px;font-weight:700}.card strong{display:block;font-size:24px;margin-top:4px}.positive{color:#197044}.negative{color:#b42318}.box{overflow:auto}table{width:100%;border-collapse:collapse;font-size:12px}th,td{padding:11px 12px;border-bottom:1px solid #c5d5de;text-align:right;white-space:nowrap}th:first-child,td:first-child{text-align:left}th{background:#e7f0f3;color:#174052;font-size:10px;text-transform:uppercase}.status{padding:4px 8px;border-radius:99px;font-weight:700}.ok{background:#e4f5ea;color:#197044}.no{background:#fff0ee;color:#b42318}@media(max-width:800px){.head{display:block}.filters{margin-top:14px}.cards{grid-template-columns:repeat(2,1fr)}select,button,label{width:100%}}</style></head><body><main><div class="head"><div><h1>Proyección de altas</h1><p class="sub">Estimación de instalaciones TOA por productividad histórica y calendario productivo.</p></div><form class="filters"><label>Período objetivo<select name="periodo"><?php foreach($periods as$p):?><option value="<?=$h($p)?>" <?=$p===$period?'selected':''?>><?=$h($label($p))?></option><?php endforeach;?></select></label><label>Tipo de instalación<select name="tipo"><?php foreach($types as$k=>$v):?><option value="<?=$h($k)?>" <?=$k===$type?'selected':''?>><?=$h($v)?></option><?php endforeach;?></select></label><label>Histórico desde<select name="desde"><?php foreach($periods as$p):?><option value="<?=$h($p)?>" <?=$p===$from?'selected':''?>><?=$h($label($p))?></option><?php endforeach;?></select></label><label>Histórico hasta<select name="hasta"><?php foreach($periods as$p):?><option value="<?=$h($p)?>" <?=$p===$to?'selected':''?>><?=$h($label($p))?></option><?php endforeach;?></select></label><button>Consultar</button></form></div><?php if($error):?><div class="card"><?=$h($error)?></div><?php else:?><div class="cards"><div class="card"><span>Realizadas período</span><strong><?=$fmt($actual)?></strong></div><div class="card"><span>Proyección total</span><strong><?=$fmt($projection)?></strong></div><div class="card"><span>Objetivo total</span><strong><?=$fmt($target)?></strong></div><div class="card"><span>Diferencia</span><strong class="<?=$projection>=$target?'positive':'negative'?>"><?=$projection>=$target?'+':''?><?=$fmt($projection-$target)?></strong></div><div class="card"><span>Tipo seleccionado</span><strong style="font-size:16px"><?=$h($types[$type])?></strong></div></div><div class="box"><table><tr><th>Grupo</th><th>Prom. lunes a viernes</th><th>Prom. sábado</th><th>Realizadas</th><th>Proyección</th><th>Objetivo</th><th>Diferencia</th><th>Resultado</th></tr><?php foreach($rows as$r):?><tr><td><b><?=$h($r['name'])?></b></td><td><?=$fmt($r['week'],1)?> / día</td><td><?=$fmt($r['sat'],1)?> / sábado</td><td><?=$fmt($r['actual'])?></td><td><b><?=$fmt($r['projection'])?></b></td><td><?=$fmt($r['target'])?></td><td class="<?=$r['diff']>=0?'positive':'negative'?>"><?=$r['diff']>=0?'+':''?><?=$fmt($r['diff'])?></td><td><span class="status <?=$r['diff']>=0?'ok':'no'?>"><?=$r['diff']>=0?'Llega':'No llega'?></span></td></tr><?php endforeach;?></table></div><p class="sub">El período actual proyecta los días restantes. El filtro usa el campo real <b>tecnologia</b> de Dataflow TOA.</p><?php endif;?></main></body></html>
